export interface FleetCounts {
  active: number;
  waiting: number;
  idle: number;
}

export interface RateLimitState {
  limited: boolean;
  retryAfterMs: number | null;
}

/** A one-line summary of the fleet's current state, including rate-limit backpressure. */
export function summarize(counts: FleetCounts, rateLimit?: RateLimitState): string {
  const base = `${counts.active} active, ${counts.waiting} waiting, ${counts.idle} idle`;
  if (!rateLimit?.limited) return base;
  const wait = rateLimit.retryAfterMs != null ? ` (retry in ${Math.ceil(rateLimit.retryAfterMs / 1000)}s)` : "";
  return `${base} - rate limited${wait}`;
}
